#!/usr/bin/env python3
"""Build Unwoke lockdown arrays from the stock snapshot.

Stock moved the lists out of flatpak.just into flatpak-permissions-lockdown.
Prefer that script. Fall back to the just file for an older snapshot.
"""
from __future__ import annotations

import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
CANDIDATES = (
    ROOT / "files/upstream-snapshots/secureblue/flatpak-permissions-lockdown",
    ROOT / "files/upstream-snapshots/secureblue/flatpak.just",
)
DST = ROOT / "files/system/usr/share/unwoke/flatpak-lockdown-lists.sh"

MAP = {
    "kSharePermissions": "share",
    "kSocketPermissions": "socket",
    "kDevicePermissions": "device",
    "kFeaturePermissions": "feature",
    "kFilesystemPermissions": "filesystem",
    "kDangerousFilesystemPermissions": "dangerous",
    "kKnownSessionBusNames": "session",
    "kKnownSystemBusNames": "system",
}

ARRAY = re.compile(
    r"^\s*(k(?:Share|Socket|Device|Feature|Filesystem|DangerousFilesystem|KnownSessionBus|KnownSystemBus|FlatsealName)\w*)"
    r"\s*=\s*\((.*?)\)\s*$",
    re.M | re.S,
)


def bash_quote(item: str) -> str:
    return "'" + item.replace("'", "'\\''") + "'"


def parse_items(inner: str) -> list[str]:
    return re.findall(r'"([^"\\]*(?:\\.[^"\\]*)*)"', inner)


def main() -> int:
    src = next((path for path in CANDIDATES if path.is_file() and "kSharePermissions" in path.read_text(encoding="utf-8")), None)
    if src is None:
        print("missing lockdown snapshot", file=sys.stderr)
        return 1
    text = src.read_text(encoding="utf-8")
    found: dict[str, list[str]] = {}
    for m in ARRAY.finditer(text):
        key, inner = m.group(1), m.group(2)
        if key not in MAP:
            continue
        items = parse_items(inner)
        if not items:
            print(f"empty array {key}", file=sys.stderr)
            return 1
        found[MAP[key]] = items
    missing = [v for v in MAP.values() if v not in found]
    if missing:
        print(f"missing arrays in snapshot: {missing}", file=sys.stderr)
        return 1
    lines = [
        "# Unwoke SecureBlue. Not affiliated with secureblue.",
        "# MIT License. Copyright (c) 2026 SeRgi270710267.",
        "# UNWOKE-SHIPPED-FIRST",
        "# shellcheck shell=bash disable=SC2034,SC2088",
        "# Generated from the stock flatpak lockdown snapshot.",
        "# Do not edit. Regenerated by extract-flatpak-lockdown-lists.py",
        "",
    ]
    for name in ("share", "socket", "device", "feature", "filesystem", "dangerous", "session", "system"):
        quoted = " ".join(bash_quote(x) for x in found[name])
        lines.append(f"{name}=({quoted})")
        lines.append("")
    DST.parent.mkdir(parents=True, exist_ok=True)
    DST.write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote {DST}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
